<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BlockBigHits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(frame)</span></span>
